logger = logging.getLogger("desktopenv.metrics.gimp")


def check_white_to_alpha_transparency(result_path, expected_path, tolerance=30):
    """
    Evaluator for task: Convert white pixels (#FFFFFF) to transparent with tolerance

    This function checks:
    1. The result image has an alpha channel (transparency)
    2. The result image has transparent areas where the source had white/light pixels
    3. The non-background content (non-white areas) is preserved in the result

    Args:
        result_path: Result image path (output file with transparent background) - from VM
        expected_path: Source image path (original image with white background) - from cloud
        tolerance: Tolerance value for white detection (0-255)

    Returns:
        float: 1.0 if success, 0.0 if failure
    """
    import os
    import logging
    from PIL import Image
    import numpy as np

    logger = logging.getLogger(__name__)

    if expected_path is None or result_path is None:
        logger.warning("Expected or result path is None")
        return 0.0

    if not os.path.exists(expected_path) or not os.path.exists(result_path):
        logger.error(f"File not found: expected={expected_path}, result={result_path}")
        return 0.0

    try:
        source_img = Image.open(expected_path)
        result_img = Image.open(result_path)

        # Check if result image has alpha channel
        has_alpha = result_img.mode in ('RGBA', 'LA') or 'transparency' in result_img.info

        if not has_alpha:
            logger.warning(f"Result image has no alpha channel, mode={result_img.mode}")
            return 0.0

        # Convert to RGBA for consistent processing
        if source_img.mode != 'RGBA':
            source_img = source_img.convert('RGBA')
        if result_img.mode != 'RGBA':
            result_img = result_img.convert('RGBA')

        # Ensure same size
        if source_img.size != result_img.size:
            logger.warning(f"Size mismatch: source={source_img.size}, result={result_img.size}")
            result_img = result_img.resize(source_img.size, Image.Resampling.LANCZOS)

        source_array = np.array(source_img)
        result_array = np.array(result_img)

        # Extract alpha channel from result
        result_alpha = result_array[:, :, 3]

        # Check if there are transparent pixels in result
        result_transparent_pixels = np.sum(result_alpha < 255)
        total_pixels = result_alpha.size
        result_transparent_ratio = result_transparent_pixels / total_pixels

        logger.info(f"Result transparent pixels: {result_transparent_pixels}/{total_pixels} ({result_transparent_ratio:.2%})")

        # There should be some transparent area (background was removed)
        if result_transparent_ratio < 0.1:
            logger.warning(f"Too few transparent pixels in result: {result_transparent_ratio:.2%}")
            return 0.0

        # Identify white/light pixels in source image (these should be transparent in result)
        # Calculate average RGB value per pixel
        source_rgb = source_array[:, :, :3].astype(float)
        source_brightness = np.mean(source_rgb, axis=2)

        # White pixels have high brightness (close to 255)
        # With tolerance, pixels with brightness > (255 - tolerance) are considered "white"
        threshold = 255 - tolerance
        white_pixels_in_source = source_brightness > threshold

        white_ratio = np.sum(white_pixels_in_source) / total_pixels
        logger.info(f"White pixels in source: {np.sum(white_pixels_in_source)}/{total_pixels} ({white_ratio:.2%})")

        # Check if white pixels in source are transparent in result
        transparent_in_result = result_alpha < 128  # Mostly transparent
        white_became_transparent = np.sum(white_pixels_in_source & transparent_in_result)
        white_transparent_ratio = white_became_transparent / np.sum(white_pixels_in_source) if np.sum(white_pixels_in_source) > 0 else 0

        logger.info(f"White pixels that became transparent: {white_transparent_ratio:.2%}")

        # Check that non-white content is preserved (visible in result)
        non_white_in_source = ~white_pixels_in_source
        visible_in_result = result_alpha > 128  # Mostly visible
        non_white_preserved = np.sum(non_white_in_source & visible_in_result)
        non_white_preserved_ratio = non_white_preserved / np.sum(non_white_in_source) if np.sum(non_white_in_source) > 0 else 0

        logger.info(f"Non-white content preserved: {non_white_preserved_ratio:.2%}")

        # Success criteria:
        # 1. Has alpha channel
        # 2. Has some transparent area
        # 3. Most white pixels became transparent (> 50%)
        # 4. Most non-white content is preserved (> 50%)
        success = (
            has_alpha and
            result_transparent_ratio > 0.1 and
            white_transparent_ratio > 0.5 and
            non_white_preserved_ratio > 0.5
        )

        result = 1.0 if success else 0.0
        logger.info(f"check_white_to_alpha_transparency result: {result} " +
                   f"(has_alpha={has_alpha}, transparent_ratio={result_transparent_ratio:.2f}, " +
                   f"white_transparent={white_transparent_ratio:.2f}, preserved={non_white_preserved_ratio:.2f})")

        return result

    except Exception as e:
        logger.error(f"check_white_to_alpha_transparency error: {e}")
        return 0.0
